SELECT 
  FROM bbs15_company_rule
 WHERE bbs15_company_id = #{companyId}
   AND bbs15_rule_type LIKE #{ruleType}
   AND CONCAT(bbs15_title, bbs15_company_rule_cd) ILIKE #{searchText}
 ORDER BY bbs15_company_rule_cd, bbs15_revision_no

SELECT COUNT(*)
  FROM bbs15_company_rule
 WHERE bbs15_company_id       = #{companyId}
   AND bbs15_company_rule_cd  = #{companyRuleCode}
   AND bbs15_revision_no      = #{revisionNo}
   AND bbs15_company_rule_id != #{companyRuleId}

SELECT COUNT(*)
  FROM tdm11_task_relate_rule
       INNER JOIN tdm10_task ON tdm10_task_id = tdm11_task_id
 WHERE tdm10_company_id  = #{companyId}
   AND tdm11_relate_type = #{relateType}
   AND tdm11_rule_cd     = #{ruleCode}
